import React, { useState, useEffect } from 'react';
import { Modal, Button, Badge } from 'react-bootstrap';

const PatientDetailModal = ({ show, onHide, patient, onReanalyse }) => {
  const [isReanalysing, setIsReanalysing] = useState(false);
  const [parsedRemarks, setParsedRemarks] = useState(null);

  useEffect(() => {
    if (patient) {
      if (!patient.remarks) {
        setParsedRemarks(null);
      } else if (typeof patient.remarks === 'object') {
        setParsedRemarks(patient.remarks);
      } else {
        try {
          setParsedRemarks(JSON.parse(patient.remarks));
        } catch (e) {
          console.error("Failed to parse remarks JSON:", e);
          // Store raw string if parse fails, though UI expects object
          setParsedRemarks({ clinical_summary: patient.remarks });
        }
      }
    }
  }, [patient]);

  const calculateAge = (dob) => {
    if (!dob) return '-';
    const birthDate = new Date(dob);
    const today = new Date();
    let age = today.getFullYear() - birthDate.getFullYear();
    const m = today.getMonth() - birthDate.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) {
      age--;
    }
    return age;
  };

  const isGlucoseNormal = (val) => val >= 70 && val <= 100;
  const isHbNormal = (val) => val >= 12 && val <= 17.5;
  const isCholNormal = (val) => val < 200;

  const getRiskBadgeStyle = (riskLevel) => {
    switch (riskLevel?.toUpperCase()) {
      case 'HIGH': return 'bg-red-100 text-red-800 border-red-200';
      case 'MODERATE': return 'bg-yellow-100 text-yellow-800 border-yellow-200';
      case 'LOW': return 'bg-green-100 text-green-800 border-green-200';
      default: return 'bg-gray-100 text-gray-800 border-gray-200';
    }
  };

  const handleReanalyseClick = async () => {
    setIsReanalysing(true);
    await onReanalyse(patient.id);
    setIsReanalysing(false);
  };

  if (!patient) return null;

  return (
    <Modal show={show} onHide={onHide} size="xl" centered scrollable>
      <Modal.Header closeButton className="border-b border-gray-100 px-6 py-4">
        <Modal.Title className="text-xl font-bold text-gray-800">
          Patient Profile & Diagnostics
        </Modal.Title>
      </Modal.Header>

      <Modal.Body className="p-0">
        <div className="flex flex-col md:flex-row h-full">
          {/* Left Column - Patient Information */}
          <div className="w-full md:w-1/2 p-8 bg-white">
            <h2 className="text-3xl font-bold text-gray-900 mb-1">{patient.fullName || patient.full_name}</h2>
            <p className="text-gray-500 text-sm mb-6">
              {patient.gender || 'Unknown Gender'} • {calculateAge(patient.dob || patient.date_of_birth)} years old
            </p>

            <hr className="border-gray-100 mb-6" />

            <div className="space-y-5">
              <div>
                <span className="text-gray-400 text-xs font-bold uppercase tracking-wider block mb-1">📧 Email</span>
                <span className="text-gray-800 font-medium">{patient.email}</span>
              </div>

              <div>
                <span className="text-gray-400 text-xs font-bold uppercase tracking-wider block mb-1">🎂 Date of Birth</span>
                <span className="text-gray-800 font-medium">{patient.dob || patient.date_of_birth}</span>
              </div>

              <div>
                <span className="text-gray-400 text-xs font-bold uppercase tracking-wider block mb-1">🩸 Glucose</span>
                <div className="flex items-center gap-2">
                  <span className="text-gray-800 font-medium">{patient.glucose} mg/dL</span>
                  {isGlucoseNormal(patient.glucose) 
                    ? <span className="text-green-600 text-xs font-medium bg-green-50 px-2 py-0.5 rounded flex items-center gap-1">✅ Normal</span> 
                    : <span className="text-red-600 text-xs font-medium bg-red-50 px-2 py-0.5 rounded flex items-center gap-1">⚠️ Abnormal</span>
                  }
                </div>
              </div>

              <div>
                <span className="text-gray-400 text-xs font-bold uppercase tracking-wider block mb-1">💉 Haemoglobin</span>
                <div className="flex items-center gap-2">
                  <span className="text-gray-800 font-medium">{patient.haemoglobin} g/dL</span>
                  {isHbNormal(patient.haemoglobin) 
                    ? <span className="text-green-600 text-xs font-medium bg-green-50 px-2 py-0.5 rounded flex items-center gap-1">✅ Normal</span> 
                    : <span className="text-red-600 text-xs font-medium bg-red-50 px-2 py-0.5 rounded flex items-center gap-1">⚠️ Abnormal</span>
                  }
                </div>
              </div>

              <div>
                <span className="text-gray-400 text-xs font-bold uppercase tracking-wider block mb-1">🫀 Cholesterol</span>
                <div className="flex items-center gap-2">
                  <span className="text-gray-800 font-medium">{patient.cholesterol} mg/dL</span>
                  {isCholNormal(patient.cholesterol) 
                    ? <span className="text-green-600 text-xs font-medium bg-green-50 px-2 py-0.5 rounded flex items-center gap-1">✅ Normal</span> 
                    : <span className="text-red-600 text-xs font-medium bg-red-50 px-2 py-0.5 rounded flex items-center gap-1">⚠️ Abnormal</span>
                  }
                </div>
              </div>

              <div>
                <span className="text-gray-400 text-xs font-bold uppercase tracking-wider block mb-1">📅 Record Added On</span>
                <span className="text-gray-600 text-sm">
                  {patient.createdAt || patient.created_at ? new Date(patient.createdAt || patient.created_at).toLocaleString() : 'N/A'}
                </span>
              </div>
            </div>
          </div>

          {/* Right Column - AI Health Report */}
          <div className="w-full md:w-1/2 p-8 bg-slate-50 border-l border-gray-100 flex flex-col h-full">
            <div className="flex justify-between items-start mb-6">
              <h3 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                AI Health Report
                <Badge bg="primary" className="text-[10px] font-normal uppercase tracking-wide rounded-full px-2">Gemini AI</Badge>
              </h3>

              {parsedRemarks && (
                <div className={`px-4 py-1.5 rounded-full border text-sm font-bold tracking-wide ${getRiskBadgeStyle(parsedRemarks.risk_level)}`}>
                  RISK: {parsedRemarks.risk_level || 'UNKNOWN'}
                </div>
              )}
            </div>

            <div className="flex-1 overflow-y-auto pr-2">
              {!parsedRemarks ? (
                <div className="flex flex-col items-center justify-center h-full text-center text-gray-500 space-y-3 py-12">
                  <div className="text-4xl opacity-50">🤖</div>
                  <p>No AI report generated yet.</p>
                  <p className="text-sm">Click the re-analyse button below to generate insights.</p>
                </div>
              ) : (
                <div className="space-y-6">
                  <div>
                    <h5 className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">📋 Clinical Summary</h5>
                    <p className="text-slate-700 text-sm leading-relaxed bg-white p-4 rounded-lg border border-slate-200 shadow-sm">
                      {parsedRemarks.clinical_summary || 'No summary available.'}
                    </p>
                  </div>

                  {parsedRemarks.identified_risks && parsedRemarks.identified_risks.length > 0 && (
                    <div>
                      <h5 className="text-xs font-bold text-red-600 uppercase tracking-wider mb-2 flex items-center gap-2">
                        ⚠️ Identified Risks
                      </h5>
                      <ul className="space-y-2 bg-red-50/50 p-4 rounded-lg border border-red-100">
                        {parsedRemarks.identified_risks.map((risk, i) => (
                          <li key={i} className="text-sm text-slate-700 flex items-start gap-2">
                            <span className="text-red-500 mt-0.5">•</span>
                            <span>{risk}</span>
                          </li>
                        ))}
                      </ul>
                    </div>
                  )}

                  {parsedRemarks.recommendations && parsedRemarks.recommendations.length > 0 && (
                    <div>
                      <h5 className="text-xs font-bold text-green-600 uppercase tracking-wider mb-2 flex items-center gap-2">
                        💊 Recommendations
                      </h5>
                      <ul className="space-y-2 bg-green-50/50 p-4 rounded-lg border border-green-100">
                        {parsedRemarks.recommendations.map((rec, i) => (
                          <li key={i} className="text-sm text-slate-700 flex items-start gap-2">
                            <span className="text-green-500 mt-0.5">•</span>
                            <span>{rec}</span>
                          </li>
                        ))}
                      </ul>
                    </div>
                  )}

                  {parsedRemarks.follow_up && (
                    <div>
                      <h5 className="text-xs font-bold text-blue-600 uppercase tracking-wider mb-2 flex items-center gap-2">
                        📅 Follow Up
                      </h5>
                      <p className="text-sm text-slate-700 bg-blue-50/50 p-4 rounded-lg border border-blue-100">
                        {parsedRemarks.follow_up}
                      </p>
                    </div>
                  )}
                </div>
              )}
            </div>

            <div className="mt-6 pt-4 border-t border-slate-200 flex justify-end">
              <Button 
                variant="primary" 
                onClick={handleReanalyseClick} 
                disabled={isReanalysing}
                className="bg-blue-600 hover:bg-blue-700 border-0 shadow-sm rounded-lg flex items-center gap-2 px-4 py-2 font-medium"
              >
                {isReanalysing ? (
                  <>
                    <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white"></div>
                    <span>Analysing...</span>
                  </>
                ) : (
                  <>
                    <span>🔄 Re-analyse</span>
                  </>
                )}
              </Button>
            </div>
          </div>
        </div>
      </Modal.Body>
    </Modal>
  );
};

export default PatientDetailModal;
